/**
 * Create actual files from the list which were generated by `Dumping tags for reporting bugs` on TagFolder.
 * This script reads tags from a file and creates markdown files in a structured directory format.
 * 
 * @version 1.0.0
 * @author vorotamoroz
 * @license Apache-2.0
 */

