const w = await Deno.readTextFile("./tags.txt");
const out = `./out/dump-${Date.now()}`;
await Deno.mkdir(out, { recursive: true });
const lines = w.split("\n");
const dirSet = new Set<string>();

for (const i in lines) {
  const dirName = `000${~~(Number(i) / 1000)}`.slice(-3);
  const filename = `000000${i}`.slice(-5);
  const outDir = out + "/" + dirName;
  if (!dirSet.has(outDir)) {
    await Deno.mkdir(outDir, { recursive: true });
    dirSet.add(outDir);
  }

  const line = lines[i];
  // console.log(`${filename} -> ${line}`);
  await Deno.writeTextFile(outDir + "/" + filename + ".md", line);
}